query:
SELECT ?city ?cityLabel ?oktmo ?pop ?date WHERE {
  ?city wdt:P31 wd:Q7930989 ;
        wdt:P17 wd:Q159 ;
        wdt:P764 ?oktmo ;
        p:P1082 ?popStmt .
  ?popStmt ps:P1082 ?pop .
  OPTIONAL { ?popStmt pq:P585 ?date . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "ru,en". }
}
